from typing import List, Dict, Any

class ModerationResult:
    def __init__(self, text: str, categories: Dict[str, float], decision: str = "allow"):
        self.text = text
        self.categories = categories
        self.decision = decision

class BatchModerationRequest:
    def __init__(self, texts: List[str]):
        self.texts = texts

class BatchModerationResponse:
    def __init__(self, results: List[ModerationResult]):
        self.results = results

class RedactionResult:
    def __init__(self, original_text: str, redacted_text: str, detections: List[Dict[str, Any]]):
        self.original_text = original_text
        self.redacted_text = redacted_text
        self.detections = detections

import boto3

def get_aws_client(service_name: str, region_name: str = "us-east-1", **kwargs):
    return boto3.client(service_name, region_name=region_name, **kwargs)

import boto3
from typing import List, Dict, Any
from safety_client import get_aws_client
from safety_models import BatchModerationRequest, BatchModerationResponse, ModerationResult

def moderate_batch(payload: BatchModerationRequest, config: Dict[str, Any] = None) -> BatchModerationResponse:
    config = config or {}
    client = get_aws_client("comprehend", region_name=config.get("region", "us-east-1"))

    text_segments = [{
        "Text": text
    } for text in payload.texts]

    response = client.batch_detect_toxic_content(TextSegments=text_segments, LanguageCode="en")

    results = []
    for i, result in enumerate(response["ResultList"]):
        results.append(ModerationResult(
            text=payload.texts[i],
            categories=result["Toxicity"]
        ))

    return BatchModerationResponse(results=results)

from typing import Dict, Any
from safety_models import ModerationResult

def safety_threshold(moderation_result: ModerationResult, thresholds: Dict[str, float]) -> ModerationResult:
    for category, score in moderation_result.categories.items():
        if category in thresholds and score > thresholds[category]:
            moderation_result.decision = "deny"
            return moderation_result
    moderation_result.decision = "allow"
    return moderation_result
